function(container, apiUrl, tables) {
  let stores = [];
  let categories = [];
  let isProcessing = false;

  // 初期化処理
  async function initialize() {
    try {
      // 店舗データの取得
      const storeData = await window.aivicApi.list(1); // 店舗マスタ
      stores = storeData || [];

      // 商品データから商品カテゴリを取得
      const productData = await window.aivicApi.list(2); // 商品マスタ
      const categoryIds = [...new Set((productData || []).map(p => p.商品カテゴリID).filter(Boolean))];
      categories = categoryIds.map(id => ({ id, name: `カテゴリ${id.slice(-4)}` }));

      renderStoreOptions();
      renderCategoryCheckboxes();
      setDefaultDates();
    } catch (error) {
      console.error('初期化エラー:', error);
    }
  }

  // 店舗選択肢の描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.forEach(store => {
      storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
    });
  }

  // 商品カテゴリチェックボックスの描画
  function renderCategoryCheckboxes() {
    const checkboxContainer = container.querySelector('#category-checkboxes');
    const selectAllHtml = checkboxContainer.innerHTML;

    categories.forEach(category => {
      checkboxContainer.innerHTML += `
        <label style="display: block; margin-bottom: 5px;">
          <input type="checkbox" class="category-checkbox" value="${category.id}"> ${category.name}
        </label>
      `;
    });
  }

  // デフォルト日付設定
  function setDefaultDates() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    const nextWeek = new Date(today);
    nextWeek.setDate(nextWeek.getDate() + 7);
    const lastMonth = new Date(today);
    lastMonth.setMonth(lastMonth.getMonth() - 1);

    container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
    container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];
    container.querySelector('#learning-start-date').value = lastMonth.toISOString().split('T')[0];
    container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];
  }

  // バリデーション
  function validateForm() {
    const errors = [];

    const predictionStart = container.querySelector('#prediction-start-date').value;
    const predictionEnd = container.querySelector('#prediction-end-date').value;
    const storeId = container.querySelector('#store-select').value;
    const selectedCategories = container.querySelectorAll('.category-checkbox:checked');
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;

    if (!predictionStart) errors.push('予測対象期間の開始日を選択してください');
    if (!predictionEnd) errors.push('予測対象期間の終了日を選択してください');
    if (!storeId) errors.push('店舗を選択してください');
    if (selectedCategories.length === 0) errors.push('商品カテゴリを選択してください');
    if (!selectedModel) errors.push('予測モデルを選択してください');
    if (!learningStart) errors.push('学習データ期間の開始日を入力してください');
    if (!learningEnd) errors.push('学習データ期間の終了日を入力してください');

    // 日付の妥当性チェック
    if (predictionStart && predictionEnd) {
      const startDate = new Date(predictionStart);
      const endDate = new Date(predictionEnd);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (startDate < today) errors.push('予測期間に過去の日付は指定できません');
      if (endDate < today) errors.push('予測期間に過去の日付は指定できません');
      if (endDate <= startDate) errors.push('予測期間の終了日は開始日より後の日付を選択してください');

      const diffTime = Math.abs(endDate - startDate);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) errors.push('予測期間は1年以内で設定してください');
    }

    // 学習データ期間のチェック
    if (learningStart && learningEnd && predictionStart && predictionEnd) {
      const learningStartDate = new Date(learningStart);
      const learningEndDate = new Date(learningEnd);
      const predictionStartDate = new Date(predictionStart);
      const predictionEndDate = new Date(predictionEnd);

      const learningDays = Math.ceil((learningEndDate - learningStartDate) / (1000 * 60 * 60 * 24));
      const predictionDays = Math.ceil((predictionEndDate - predictionStartDate) / (1000 * 60 * 60 * 24));

      if (learningDays < predictionDays) {
        errors.push('学習データ期間は予測期間以上に設定してください');
      }
    }

    return errors;
  }

  // エラー表示
  function showErrors(errors) {
    const errorSection = container.querySelector('#validation-errors');
    const errorList = container.querySelector('#error-list');

    if (errors.length > 0) {
      errorList.innerHTML = errors.map(error => `<li>${error}</li>`).join('');
      errorSection.classList.remove('hidden');
    } else {
      errorSection.classList.add('hidden');
    }
  }

  // 進捗バー表示
  function showProgress() {
    const progressSection = container.querySelector('#progress-section');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressSection.classList.remove('hidden');
    progressBar.style.width = '0%';
    progressText.textContent = '処理を開始しています...';

    // UI無効化
    const executeBtn = container.querySelector('#btn-execute-prediction');
    executeBtn.disabled = true;
    executeBtn.textContent = '処理中...';

    // 進捗シミュレーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 90) progress = 90;

      progressBar.style.width = progress + '%';

      if (progress < 30) {
        progressText.textContent = 'データを収集しています...';
      } else if (progress < 60) {
        progressText.textContent = 'AIモデルを学習しています...';
      } else if (progress < 90) {
        progressText.textContent = '需要予測を計算しています...';
      }
    }, 500);

    return progressInterval;
  }

  // 予測実行
  async function executePrediction() {
    const errors = validateForm();
    showErrors(errors);

    if (errors.length > 0) return;

    isProcessing = true;
    const progressInterval = showProgress();

    try {
      // 予測処理のシミュレーション
      await new Promise(resolve => setTimeout(resolve, 3000));

      // 進捗完了
      clearInterval(progressInterval);
      const progressBar = container.querySelector('#progress-bar');
      const progressText = container.querySelector('#progress-text');
      progressBar.style.width = '100%';
      progressText.textContent = '予測処理が完了しました';

      // 結果生成
      await generatePredictionResults();

      setTimeout(() => {
        container.querySelector('#progress-section').classList.add('hidden');
        container.querySelector('#prediction-results').classList.remove('hidden');
      }, 1000);

    } catch (error) {
      clearInterval(progressInterval);
      showErrors(['AI予測実行に失敗しました。システム管理者にお問い合わせください。']);
    } finally {
      isProcessing = false;
      const executeBtn = container.querySelector('#btn-execute-prediction');
      executeBtn.disabled = false;
      executeBtn.textContent = 'AI予測実行';
    }
  }

  // 予測結果生成
  async function generatePredictionResults() {
    const storeId = container.querySelector('#store-select').value;
    const selectedCategories = Array.from(container.querySelectorAll('.category-checkbox:checked')).map(cb => cb.value);
    const predictionStart = new Date(container.querySelector('#prediction-start-date').value);
    const predictionEnd = new Date(container.querySelector('#prediction-end-date').value);
    const accuracyThreshold = parseInt(container.querySelector('#accuracy-threshold').value);

    const store = stores.find(s => s.店舗ID === storeId);
    const results = [];

    // 予測結果のサンプルデータ生成
    for (let d = new Date(predictionStart); d <= predictionEnd; d.setDate(d.getDate() + 1)) {
      selectedCategories.forEach(categoryId => {
        const accuracy = Math.floor(Math.random() * 40) + 60; // 60-100%
        if (accuracy >= accuracyThreshold) {
          const predictedQty = Math.floor(Math.random() * 100) + 10;
          const recommendedOrder = Math.ceil(predictedQty * 1.1);

          results.push({
            店舗名: store.店舗名,
            商品名: `商品${categoryId.slice(-4)}`,
            予測日: new Date(d).toISOString().split('T')[0],
            予測数量: predictedQty,
            予測精度: accuracy,
            推奨発注数量: recommendedOrder
          });
        }
      });
    }

    // 結果をテーブルに表示
    const tbody = container.querySelector('#results-tbody');
    tbody.innerHTML = results.map(result => `
      <tr>
        <td>${result.店舗名}</td>
        <td>${result.商品名}</td>
        <td>${result.予測日}</td>
        <td>${result.予測数量}</td>
        <td>${result.予測精度}%</td>
        <td>${result.推奨発注数量}</td>
        <td>
          <button class="action-btn secondary" onclick="window.showScreen('scr-1778591852463')">発注管理へ</button>
        </td>
      </tr>
    `).join('');
  }

  // 天候データ取込
  async function importWeatherData() {
    try {
      // 天候データ取込のシミュレーション
      const weatherData = {
        店舗ID: container.querySelector('#store-select').value || stores[0]?.店舗ID,
        観測日: new Date().toISOString(),
        天気: '晴れ',
        最高気温: 25,
        最低気温: 15,
        平均気温: 20,
        降水量: 0,
        湿度: 60,
        風速: 3,
        データ種別: '予報値',
        データソース: '気象庁API'
      };

      const saved = await window.aivicApi.save(4, weatherData); // 天候データテーブル
      if (saved) {
        alert('天候データの取込が完了しました');
      } else {
        alert('天候データの取得に失敗しました。データソースの設定を確認してください。');
      }
    } catch (error) {
      alert('天候データの取得に失敗しました。データソースの設定を確認してください。');
    }
  }

  // イベントデータ取込
  async function importEventData() {
    try {
      // イベントデータ取込のシミュレーション
      const eventData = {
        店舗ID: container.querySelector('#store-select').value || stores[0]?.店舗ID,
        イベント名: 'サンプルイベント',
        イベント種別: '祭り',
        開始日時: new Date().toISOString(),
        終了日時: new Date(Date.now() + 86400000).toISOString(),
        予想来場者数: 1000,
        影響度: '中',
        場所: '駅前広場',
        店舗からの距離: 500,
        備考: '自動取得データ',
        有効フラグ: true
      };

      const saved = await window.aivicApi.save(5, eventData); // イベントデータテーブル
      if (saved) {
        alert('イベントデータの取込が完了しました');
      } else {
        alert('イベントデータの取込に失敗しました。ファイル形式を確認してください。');
      }
    } catch (error) {
      alert('イベントデータの取込に失敗しました。ファイル形式を確認してください。');
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-execute-prediction').addEventListener('click', executePrediction);
  container.querySelector('#btn-weather-import').addEventListener('click', importWeatherData);
  container.querySelector('#btn-event-import').addEventListener('click', importEventData);

  // 全選択チェックボックス
  container.querySelector('#select-all-categories').addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.category-checkbox');
    checkboxes.forEach(cb => cb.checked = this.checked);
  });

  // 季節要因スライダー
  container.querySelector('#seasonal-factor').addEventListener('input', function() {
    container.querySelector('#seasonal-value').textContent = this.value + '%';
  });

  // 処理中の操作無効化
  container.addEventListener('click', function(e) {
    if (isProcessing && !e.target.closest('#progress-section')) {
      e.preventDefault();
      e.stopPropagation();
    }
  });

  // 初期化実行
  initialize();
}
